BEGIN; SET LOCAL lock_timeout='1s'; SET LOCAL statement_timeout='20s';
CREATE TEMP TABLE tick_v6_test_result(proof jsonb) ON COMMIT DROP;
DO $test$
DECLARE before_state jsonb;after_state jsonb;good boolean;rv bigint;checks integer:=0;started timestamptz:=clock_timestamp(); code constant text:=$code$-- Exact tick-only measured admission; no source/transport/adapter/task changes.
DO $tick_v6$
DECLARE ctl jsonb;q record;v record;a record;p record;before_state jsonb;after_state jsonb;used bigint;available bigint;rv bigint;
BEGIN
IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RAISE EXCEPTION 'TICK_V6_QUIET_LOCK_BUSY';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'TICK_V6_QUIET_WORK_REQUIRED';END IF;
ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT * INTO STRICT q FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='resource:9511985d8ae4986d9a99ac4b3b59d157cd336c06e178f6dfd1d510092c0281f9' FOR UPDATE;
IF q.status IS DISTINCT FROM 'CLAIMED' OR q.claim_token_sha256 IS DISTINCT FROM '144007c009bee9848caf4f69ee38e1d4c92100c82dbc036c12a3f689af956159' OR q.assignment_event_id<>46168 OR q.input_sha256 IS DISTINCT FROM '9511985d8ae4986d9a99ac4b3b59d157cd336c06e178f6dfd1d510092c0281f9' OR q.claim_expires_at IS NULL OR q.claim_expires_at<=clock_timestamp() OR q.not_after IS NULL OR q.not_after<=clock_timestamp() OR q.owner_id IS DISTINCT FROM ctl->>'owner_id' OR q.owner_fence<>3 OR q.stop_generation<>1 OR q.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR q.assigned_executor IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=46603 AND event='ENGINEERING_CLEARING_CLAIMED_V6' AND details->>'clearing_id'=q.clearing_id) THEN RAISE EXCEPTION 'TICK_V6_EXACT_CURRENT_CLAIM';END IF;
SELECT * INTO STRICT v FROM population_top3000_202608_202609_v1.resource_probe_v3 WHERE probe_id='7383ce2b-db79-4136-9698-431c7f76d503';
IF v.state IS DISTINCT FROM 'SUCCEEDED' OR v.owner_id IS DISTINCT FROM ctl->>'owner_id' OR v.owner_fence<>3 OR v.stop_generation<>1 OR v.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' OR v.result_sha256 IS DISTINCT FROM 'd847fbcefb672b2a09917a256ff5a85dcd7e4fa9f96abdc97b204da769fec9e6' OR v.result_sha256 IS DISTINCT FROM encode(sha256(convert_to(v.result::text,'UTF8')),'hex') OR v.result->>'observed_at' IS NULL OR (v.result->>'observed_at')::timestamptz<clock_timestamp()-interval '10 minutes' OR (v.result->>'observed_at')::timestamptz>clock_timestamp() THEN RAISE EXCEPTION 'TICK_V6_FRESH_PROBE';END IF;
IF current_setting('data_directory') NOT LIKE '/data/%' OR (SELECT count(*) FROM jsonb_array_elements(v.result->'metrics')m WHERE m->>'mountpoint'='/data')<>1 THEN RAISE EXCEPTION 'TICK_V6_DATA_MOUNT';END IF;
SELECT (m->>'available_bytes')::bigint INTO available FROM jsonb_array_elements(v.result->'metrics')m WHERE m->>'mountpoint'='/data';
SELECT sum(pg_total_relation_size(oid)) INTO used FROM pg_class WHERE relnamespace='population_top3000_202608_202609_v1'::regnamespace AND relkind IN('r','m');
SELECT * INTO STRICT a FROM population_top3000_202608_202609_v1.acquisition_control WHERE singleton;
SELECT * INTO STRICT p FROM population_top3000_202608_202609_v1.pipeline_control WHERE singleton;
IF p.max_ticks<>26000 OR p.tick_count<22880 OR p.tick_count>=26000 OR p.budget_evidence#>>'{resource_limits,max_total_ticks}' IS DISTINCT FROM '26000' OR p.deadline IS DISTINCT FROM '2026-10-25T22:36:17.687194Z'::timestamptz OR a.max_source_bytes<>1500000000 OR a.max_provider_requests<>11000 OR a.max_http_invocations<>11055 OR a.max_dispatch_calls<>21600 OR p.budget_evidence#>>'{resource_limits,max_relation_bytes}' IS DISTINCT FROM '12000000000' OR a.stored_bytes+a.reserved_bytes>=a.max_source_bytes OR used>=12000000000 OR available-greatest(12000000000-used,0)-greatest(1500000000-a.stored_bytes-a.reserved_bytes,0)-a.reserved_bytes<20000000000 THEN RAISE EXCEPTION 'TICK_V6_EXACT_PREIMAGE_OR_HEADROOM';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'TICK_V6_ACTIVE_WORK_RETRY_LATER';END IF;
SELECT event_id INTO rv FROM population_top3000_202608_202609_v1.pipeline_event WHERE event='RESOURCE_TICK_V6_INDEPENDENT_REVIEW' AND details->>'approved'='true' AND details->>'claim_event_id'='46603' AND details->>'clearing_id'=q.clearing_id AND details->>'input_sha256'=q.input_sha256 AND details->>'probe_result_sha256'=v.result_sha256 AND details->>'old_max_ticks'='26000' AND details->>'new_max_ticks'='30000' AND details->>'owner_id'=ctl->>'owner_id' AND details->>'owner_fence'='3' AND details->>'stop_generation'='1' AND details->>'scope_sha256'=ctl->>'scope_sha256' AND nullif(details->>'producer','') IS NOT NULL AND nullif(details->>'reviewer','') IS NOT NULL AND details->>'producer' IS DISTINCT FROM details->>'reviewer' ORDER BY event_id DESC LIMIT 1;
IF rv IS NULL THEN RAISE EXCEPTION 'TICK_V6_EXACT_INDEPENDENT_REVIEW';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id='da79b746-8550-41c9-a6f0-3d87f4e352fd' AND status IN('READY','BLOCKED')) THEN RAISE EXCEPTION 'TICK_V6_CONTINUING_TASK';END IF;
before_state:=jsonb_build_object('acquisition',to_jsonb(a),'pipeline',to_jsonb(p)-ARRAY['max_ticks','budget_evidence'],'budget',p.budget_evidence#-'{resource_limits,max_total_ticks}','manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'options_policy',(SELECT to_jsonb(h) FROM population_top3000_202608_202609_v1.continuation_handler_v6 h WHERE kind='CTX02_PAGE_ADMISSION'));
UPDATE population_top3000_202608_202609_v1.pipeline_control SET max_ticks=30000,budget_evidence=jsonb_set(budget_evidence,'{resource_limits,max_total_ticks}','30000') WHERE singleton;
SELECT jsonb_build_object('acquisition',to_jsonb(ac),'pipeline',to_jsonb(pc)-ARRAY['max_ticks','budget_evidence'],'budget',pc.budget_evidence#-'{resource_limits,max_total_ticks}','manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1(),'options_policy',(SELECT to_jsonb(h) FROM population_top3000_202608_202609_v1.continuation_handler_v6 h WHERE kind='CTX02_PAGE_ADMISSION')) INTO after_state FROM population_top3000_202608_202609_v1.acquisition_control ac CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE ac.singleton AND pc.singleton;
IF before_state IS DISTINCT FROM after_state THEN RAISE EXCEPTION 'TICK_V6_COUNTER_HISTORY_CODE_OTHER_BOUND_CHANGED';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('CONTINUATION_MEASURED_ADMISSION_V6',ctl||jsonb_build_object('admission_class','TICK_ONLY_FINITE_MEASURED_V6','actor','automation:6adc2c96db348191bca7cf4eacfdac32','clearing_id',q.clearing_id,'input_sha256',q.input_sha256,'claim_event_id',46603,'probe_id',v.probe_id,'probe_result_sha256',v.result_sha256,'available_bytes',available,'mission_relation_bytes',used,'old_max_ticks',26000,'new_max_ticks',30000,'independent_review_event_id',rv,'effects_known',true,'cumulative_counters_preserved',true,'original_deadline_preserved',true,'source_holds_unchanged',true,'no_source_acquisition',true,'code_manifest_unchanged',true,'successor_task_id','da79b746-8550-41c9-a6f0-3d87f4e352fd','family_accepted',false));
END $tick_v6$;
$code$;
BEGIN
IF NOT pg_try_advisory_xact_lock(2026083000261022) THEN RAISE EXCEPTION 'TEST_QUIET_LOCK_BUSY';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_attempt WHERE outcome='RUNNING') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'TEST_QUIET_WORK_REQUIRED';END IF;
PERFORM population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT jsonb_build_object('a',to_jsonb(a),'p',to_jsonb(p),'options',(select to_jsonb(h)from population_top3000_202608_202609_v1.continuation_handler_v6 h where kind='CTX02_PAGE_ADMISSION'),'tasks',(select jsonb_agg(to_jsonb(t) order by task_id)from population_top3000_202608_202609_v1.pipeline_task t where task_id in('d377d980-5dbd-4276-a2c9-d5638c60b668','da79b746-8550-41c9-a6f0-3d87f4e352fd','f55551ce-df3f-4726-8c16-855b93a92d21'))) INTO before_state FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
-- Synthetic review is contained in this whole rolled-back test transaction.
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('RESOURCE_TICK_V6_INDEPENDENT_REVIEW',jsonb_build_object('fixture_only',true,'approved',true,'claim_event_id',46603,'clearing_id','resource:9511985d8ae4986d9a99ac4b3b59d157cd336c06e178f6dfd1d510092c0281f9','input_sha256','9511985d8ae4986d9a99ac4b3b59d157cd336c06e178f6dfd1d510092c0281f9','probe_result_sha256','d847fbcefb672b2a09917a256ff5a85dcd7e4fa9f96abdc97b204da769fec9e6','old_max_ticks',26000,'new_max_ticks',30000,'owner_id','top3000-completion-20261024-root-5db48b32d103','owner_fence',3,'stop_generation',1,'scope_sha256','8e6ca1178f03822c34bb1b339818b34dcfdbf2a8642ef875e6e1af34dbf1bedd','producer','automation:6adc2c96db348191bca7cf4eacfdac32','reviewer','primary-independent-review-rollback-fixture')) RETURNING event_id INTO rv;
BEGIN
 EXECUTE code;
 IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_control WHERE max_ticks=30000 AND budget_evidence#>>'{resource_limits,max_total_ticks}'='30000') THEN RAISE EXCEPTION 'POSITIVE_CHANGE_MISSING';END IF;
 good:=false; BEGIN EXECUTE code; EXCEPTION WHEN OTHERS THEN IF SQLERRM='TICK_V6_EXACT_PREIMAGE_OR_HEADROOM' THEN good:=true;ELSE RAISE;END IF;END;
 IF NOT good THEN RAISE EXCEPTION 'SPENT_PREIMAGE_NOT_REJECTED';END IF;
 RAISE EXCEPTION 'POSITIVE_ROLLBACK_SENTINEL';
EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'POSITIVE_ROLLBACK_SENTINEL' THEN RAISE;END IF;
END;checks:=checks+2;
good:=false; BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET max_provider_requests=10999 WHERE singleton;
 EXECUTE code; RAISE EXCEPTION 'NEGATIVE_NOT_REJECTED_wrong_preimage'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='TICK_V6_EXACT_PREIMAGE_OR_HEADROOM' THEN good:=true;ELSE RAISE;END IF;END; IF NOT good THEN RAISE EXCEPTION 'BAD_NEGATIVE_wrong_preimage';END IF; checks:=checks+1;
good:=false; BEGIN UPDATE population_top3000_202608_202609_v1.resource_probe_v3 SET result=jsonb_set(result,'{observed_at}',to_jsonb('2000-01-01T00:00:00Z'::text)) WHERE probe_id='7383ce2b-db79-4136-9698-431c7f76d503';
 EXECUTE code; RAISE EXCEPTION 'NEGATIVE_NOT_REJECTED_stale_probe'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='TICK_V6_FRESH_PROBE' THEN good:=true;ELSE RAISE;END IF;END; IF NOT good THEN RAISE EXCEPTION 'BAD_NEGATIVE_stale_probe';END IF; checks:=checks+1;
good:=false; BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton;
 EXECUTE code; RAISE EXCEPTION 'NEGATIVE_NOT_REJECTED_later_stop'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='CONTINUATION_USER_OR_CONTROL_HOLD' THEN good:=true;ELSE RAISE;END IF;END; IF NOT good THEN RAISE EXCEPTION 'BAD_NEGATIVE_later_stop';END IF; checks:=checks+1;
good:=false; BEGIN UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_id='synthetic-stale-owner' WHERE singleton;
 EXECUTE code; RAISE EXCEPTION 'NEGATIVE_NOT_REJECTED_stale_owner'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='CONTINUATION_OWNER_STOP_SCOPE_CHANGED' THEN good:=true;ELSE RAISE;END IF;END; IF NOT good THEN RAISE EXCEPTION 'BAD_NEGATIVE_stale_owner';END IF; checks:=checks+1;
good:=false; BEGIN DELETE FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=rv;
 EXECUTE code; RAISE EXCEPTION 'NEGATIVE_NOT_REJECTED_missing_review'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='TICK_V6_EXACT_INDEPENDENT_REVIEW' THEN good:=true;ELSE RAISE;END IF;END; IF NOT good THEN RAISE EXCEPTION 'BAD_NEGATIVE_missing_review';END IF; checks:=checks+1;
good:=false; BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED' WHERE task_id='da79b746-8550-41c9-a6f0-3d87f4e352fd';
 EXECUTE code; RAISE EXCEPTION 'NEGATIVE_NOT_REJECTED_quiet_preflight'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='TICK_V6_QUIET_WORK_REQUIRED' THEN good:=true;ELSE RAISE;END IF;END; IF NOT good THEN RAISE EXCEPTION 'BAD_NEGATIVE_quiet_preflight';END IF; checks:=checks+1;
SELECT jsonb_build_object('a',to_jsonb(a),'p',to_jsonb(p),'options',(select to_jsonb(h)from population_top3000_202608_202609_v1.continuation_handler_v6 h where kind='CTX02_PAGE_ADMISSION'),'tasks',(select jsonb_agg(to_jsonb(t) order by task_id)from population_top3000_202608_202609_v1.pipeline_task t where task_id in('d377d980-5dbd-4276-a2c9-d5638c60b668','da79b746-8550-41c9-a6f0-3d87f4e352fd','f55551ce-df3f-4726-8c16-855b93a92d21'))) INTO after_state FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control p WHERE a.singleton AND p.singleton;
IF before_state IS DISTINCT FROM after_state THEN RAISE EXCEPTION 'COUNTER_POLICY_TASK_CONTROLS_NOT_RESTORED';END IF;checks:=checks+1;
INSERT INTO tick_v6_test_result VALUES(jsonb_build_object('result','PASS_TICK_ONLY_26000_TO_30000_ROLLBACK','checks',checks,'controls_policy_tasks_preserved',true,'elapsed_seconds',extract(epoch from clock_timestamp()-started),'source_calls',0,'code_manifest',population_top3000_202608_202609_v1.population_recovery_manifest_v1()));
END $test$;
SELECT proof FROM tick_v6_test_result;
ROLLBACK;
